// The supplier-mailbox reading is told who the sender is and the Auto-Submitted header as facts; a second reading of a known
// sender's 'unclear' mail must decide; a known sender's auto-generated mail the MODEL allowed is not refused by the header alone.
import { assert, assertEquals } from 'jsr:@std/assert@1';
import { isSecondReading, knownFact, readAllowsAutoGenerated, readingInput, SECOND_READING } from './supplier_mailbox_reading.ts';

const mail = (raw: Record<string, unknown> = {}) => ({ id: 1, from_email: 'Ops <ops@firm.ae>', to_email: 'supplier@quotesdone.com', subject: 'Re: invitation', body: 'Yes, how do we register?', raw });

Deno.test('the reading is given what code knows: the sender\'s relation and the header', () => {
  const s = readingInput(mail({ auto_submitted: 'auto-generated' }), [], { known: 'supplier' });
  assert(s.includes(knownFact('supplier')), s);
  assert(s.includes('Auto-Submitted header says "auto-generated"'), s);
  assert(!s.includes(SECOND_READING), 'not a second reading unless the duty asked for one');
  assert(readingInput(mail(), [], { known: null }).includes(knownFact(null)));
  assert(!readingInput(mail(), []).includes('Known to QuotesDone'), 'the old call shape is unchanged');
});

Deno.test('a second reading is asked only of a known sender\'s mail the duty put back', () => {
  const back = mail({ second_reading_requested_at: '2026-11-16T10:00:00Z' });
  assertEquals(isSecondReading(back, 'supplier'), true);
  assertEquals(isSecondReading(back, null), false, 'a stranger keeps "unclear": a wrong answer would go to a stranger');
  assertEquals(isSecondReading(mail(), 'customer'), false);
  assert(readingInput(back, [], { known: 'customer' }).includes(SECOND_READING));
  assert(!readingInput(back, [], { known: null }).includes(SECOND_READING));
});

Deno.test('the last code check: only a model reading that allowed an answer lifts exactly "auto-generated"', () => {
  const gen = mail({ auto_submitted: 'auto-generated' });
  assertEquals(readAllowsAutoGenerated(gen, { may_reply: true, method: 'model' }).raw?.auto_submitted, '');
  assertEquals(readAllowsAutoGenerated(gen, { may_reply: true, method: 'code' }).raw?.auto_submitted, 'auto-generated');
  assertEquals(readAllowsAutoGenerated(gen, { may_reply: false, method: 'model' }).raw?.auto_submitted, 'auto-generated');
  assertEquals(readAllowsAutoGenerated(mail({ auto_submitted: 'auto-replied' }), { may_reply: true, method: 'model' }).raw?.auto_submitted, 'auto-replied', 'an out-of-office stays refused');
  assertEquals(readAllowsAutoGenerated(gen, null).raw?.auto_submitted, 'auto-generated');
});
